/**
 * Shared translations for the SmartHomeShop panel.
 *
 * The panel follows the language selected in Home Assistant. Region variants
 * such as `nl-NL` and `de-DE` resolve to their base language. Unsupported
 * languages fall back to English.
 */

export const SUPPORTED_PANEL_LANGUAGES = ['en', 'nl', 'de', 'fr', 'es'] as const;
export type SupportedPanelLanguage = typeof SUPPORTED_PANEL_LANGUAGES[number];

type HassLanguage = { language?: string; locale?: { language?: string } };

