    "Dynamic prices, solar, battery, EV and inverter automations are configured once for the whole home under Energy settings.": "Automatiseringen voor dynamische prijzen, zonne-energie, batterij, EV en omvormer stel je één keer in voor het hele huis onder Energie-instellingen.",
