    "One connection unlocks live dynamic prices, cheapest-hours planning, deadline schedules and battery control. Create a free API key in your account and paste it here.": "Eén verbinding geeft toegang tot live dynamische prijzen, planning op de goedkoopste uren, deadlineschema's en batterijbesturing. Maak een gratis API-sleutel aan in je account en plak die hier.",
    "One-click automations for this device - pick the ones you want and choose where the notification goes. Each becomes a normal Home Assistant automation you can fine-tune later in the automation editor.": "Automatiseringen met één klik voor dit apparaat. Kies welke je wilt en waar de melding heen gaat. Elke keuze wordt een normale Home Assistant-automatisering die je later kunt verfijnen in de automatiseringsbewerker.",
    "Online": "Online",
