    "State-of-charge sensor": "Sensor batterijstatus",
    "Steer devices around prices and solar production. Loads can run in cheap or surplus hours, while inverter output can be reduced safely to avoid unwanted export. Each setup creates a normal, editable Home Assistant automation with restart recovery and fail-safe behaviour.": "Stuur apparaten op prijzen en zonneproductie. Verbruikers kunnen draaien in goedkope uren of bij overschot, terwijl het vermogen van de omvormer veilig kan worden verlaagd om ongewenste teruglevering te voorkomen. Elke instelling maakt een normale, bewerkbare Home Assistant-automatisering met herstel na een herstart en veilig gedrag bij storingen.",
    "Surplus needed": "Benodigd overschot",
    "Switch a deferrable load (boiler, pump, ventilation) on during the cheapest contiguous block of the day and off when it ends.": "Schakel een uitstelbare verbruiker (boiler, pomp, ventilatie) in tijdens het goedkoopste aaneengesloten blok van de dag en uit wanneer dat eindigt.",
    "Switch a load off when the price level hits its daily peak and back on when it drops. Trims the most expensive hours.": "Schakel een verbruiker uit wanneer het prijsniveau zijn dagpiek bereikt en weer in wanneer het daalt. Vermijdt de duurste uren.",
    "Switch a load on when the house exports more than it needs, and off when you would start importing - with hysteresis + dwell so it does not flap.": "Schakel een verbruiker in wanneer het huis meer teruglevert dan het nodig heeft, en uit wanneer je zou gaan afnemen. Met hysterese en wachttijd, zodat hij niet steeds aan en uit schakelt.",
