    "When the feed-in price goes negative (you would pay to export), switch on a diversion load to self-consume instead. Off again when feed-in is positive.": "Wanneer de terugleverprijs negatief wordt en je dus betaalt voor teruglevering, schakel je een extra verbruiker in om de energie zelf te gebruiken. Schakel hem weer uit zodra de terugleverprijs positief is.",
