    "Your API key works, but the selected location has no active energy contract, so there are no prices to plan against. Add or activate a contract in your SmartHomeShop account, or pick another location in Settings.": "Je API-sleutel werkt, maar de geselecteerde locatie heeft geen actief energiecontract, dus er zijn geen prijzen om op te plannen. Voeg een contract toe of activeer het in je SmartHomeShop-account, of kies een andere locatie in Instellingen.",
    "Your P1 meter covers the grid. If you have solar panels or a home battery, connect their sensors so the Energy tab shows real surplus and state of charge. You can always do this later from Settings.": "Je P1-meter dekt het net af. Als je zonnepanelen of een thuisbatterij hebt, verbind dan hun sensoren, zodat het tabblad Energie het echte overschot en de batterijstatus laat zien. Je kunt dit altijd later doen via Instellingen.",
    "Your P1 meter only sees the grid. Connect your solar and battery entities (you already have them in Home Assistant) so we can see real solar surplus and your battery's charge level.": "Je P1-meter ziet alleen het net. Verbind je entiteiten voor zonne-energie en batterij (die heb je al in Home Assistant), zodat we het echte zonneoverschot en het laadniveau van je batterij kunnen zien.",
    "Your polygon zone is drawn! Choose what type this zone should be.": "Je polygoonzone is getekend! Kies welk type deze zone moet zijn.",
