    "Reflection protection enabled": "Reflexionsschutz aktiviert",
    "Visual only": "Nur visuell",
    "No mirrors added yet.": "Noch keine Spiegel hinzugefügt.",
    "Place the mirror on its real wall. Optional reflection protection filters predicted ghost targets behind it.": "Platziere den Spiegel an seiner tatsächlichen Wand. Der optionale Reflexionsschutz filtert vorhergesagte Geisterziele dahinter.",
    "Place the mirror on the wall where it is physically installed.": "Platziere den Spiegel an der Wand, an der er tatsächlich montiert ist.",
    "Filter ghost targets predicted behind this mirror and send the area to each linked radar as an exclusion polygon.": "Filtert vorhergesagte Geisterziele hinter diesem Spiegel und sendet den Bereich als Ausschlusspolygon an jedes verknüpfte Radar.",
    "Protection depth (cm)": "Schutztiefe (cm)",
    "The dashed preview follows the radar rays beyond the mirror. Increase the depth only when ghost targets appear farther behind it.": "Die gestrichelte Vorschau folgt den Radarstrahlen hinter den Spiegel. Erhöhe die Tiefe nur, wenn Geisterziele weiter dahinter erscheinen.",
    "Each protected mirror uses one of the radar's two exclusion slots. Raw diagnostic target entities remain unchanged; Room Designer, the UltimateSensor room view and firmware people counting ignore the protected area.": "Jeder geschützte Spiegel nutzt einen der zwei Ausschlussplätze des Radars. Rohe Diagnose-Zielentitäten bleiben unverändert; Room Designer, die UltimateSensor-Raumansicht und die Personenzählung der Firmware ignorieren den geschützten Bereich.",
    "{used}/2 radar exclusion slots used.": "{used}/2 Radar-Ausschlussplätze verwendet.",
    "Disable protection for a mirror or remove a manual exclusion before pushing.": "Deaktiviere den Schutz eines Spiegels oder entferne einen manuellen Ausschluss vor dem Übertragen.",
    "Link a radar placement to preview and use reflection protection. The mirror can still be saved visually.": "Verknüpfe eine Radarplatzierung, um den Reflexionsschutz anzuzeigen und zu nutzen. Der Spiegel kann trotzdem visuell gespeichert werden.",
    "Reflection protection needs {total} exclusion slots for {sensor}, but the radar supports 2. Disable protection for a mirror or remove a manual exclusion zone.": "Der Reflexionsschutz benötigt {total} Ausschlussplätze für {sensor}, das Radar unterstützt aber nur 2. Deaktiviere den Schutz eines Spiegels oder entferne eine manuelle Ausschlusszone.",
    "Edit mirror {number}": "Spiegel {number} bearbeiten",
