    "{name} has {count} vertices. LD2450 and LD2460 polygons support at most 20.": "{name} hat {count} Eckpunkte. LD2450- und LD2460-Polygone unterstützen höchstens 20 Punkte.",
    "Remove {name}?": "{name} entfernen?",
    "Remove {name}": "{name} entfernen",
