    "\"Cheap\" here means below the daily average price, not the single cheapest window. Use \"Run in the cheapest hours\" for that.": "„Günstig“ heißt hier unter dem Tagesdurchschnittspreis, nicht das günstigste Zeitfenster. Nutze dafür „In den günstigsten Stunden laufen lassen“.",
