    "Click to add corners. Click the first point to close the room. Esc cancels, Ctrl+Z undoes.": "Klicke, um Ecken hinzuzufügen. Klicke auf den ersten Punkt, um den Raum zu schließen. Esc bricht ab, Strg+Z macht rückgängig.",
    "Click to add points. Click the green point to close. Drag points to move them. Right-click a point to delete it.": "Klicke, um Punkte hinzuzufügen. Klicke auf den grünen Punkt, um zu schließen. Ziehe Punkte, um sie zu verschieben. Klicke mit der rechten Maustaste auf einen Punkt, um ihn zu löschen.",
