    "Connect": "Verbinden",
    "Connect once here to use your fixed, variable or dynamic energy contract across SmartHomeShop Energy. The integration keeps working locally without an account.": "Verbinde dich hier einmal, um deinen festen, variablen oder dynamischen Energievertrag in ganz SmartHomeShop Energy zu nutzen. Die Integration funktioniert auch ohne Konto lokal weiter.",
    "Connect or select a P1 meter before linking the Home Assistant Energy Dashboard.": "Verbinde oder wähle einen P1-Zähler, bevor du das Energie-Dashboard von Home Assistant verknüpfst.",
    "Connect or select a P1 meter first to configure smart energy automations.": "Verbinde oder wähle zuerst einen P1-Zähler, um Smart-Energy-Automationen zu konfigurieren.",
    "Connect the selected P1 meter to the native HA Energy Dashboard or import compatible HA source mappings into Smart Energy.": "Verknüpfe den ausgewählten P1-Zähler mit dem eigenen Energie-Dashboard von HA oder importiere kompatible HA-Quellenzuordnungen in Smart Energy.",
    "Connect your SmartHomeShop account to get dynamic prices, cheapest-hours planning and automated control.": "Verbinde dein SmartHomeShop-Konto, um dynamische Preise, Planung nach günstigsten Stunden und automatische Steuerung zu erhalten.",
    "Connect your SmartHomeShop account, select a contract and choose the P1 meter used across Smart Energy.": "Verbinde dein SmartHomeShop-Konto, wähle einen Vertrag aus und lege den P1-Zähler fest, der in Smart Energy verwendet wird.",
    "Connect your SmartHomeShop.io devices via ESPHome, then add this integration via Settings → Devices & Services": "Verbinde deine SmartHomeShop.io-Geräte über ESPHome und füge dann diese Integration über Einstellungen → Geräte & Dienste hinzu",
    "Connected - your contract prices are being fetched.": "Verbunden. Deine Vertragspreise werden abgerufen.",
    "Connected to Home Assistant, not yet to SmartHomeShop": "Mit Home Assistant verbunden, noch nicht mit SmartHomeShop",
    "Connected, but the selected location has no active energy contract yet, so there are no prices to show.": "Verbunden, aber der ausgewählte Standort hat noch keinen aktiven Energievertrag, daher können keine Preise angezeigt werden.",
    "Connected, but this location has no active energy contract yet. Add one in your SmartHomeShop account to see prices.": "Verbunden, aber dieser Standort hat noch keinen aktiven Energievertrag. Füge in deinem SmartHomeShop-Konto einen hinzu, um Preise zu sehen.",
    "Connecting to the price service. Your prices appear here as soon as the first sync finishes.": "Verbindung zum Preisdienst wird hergestellt. Deine Preise erscheinen hier, sobald die erste Synchronisierung abgeschlossen ist.",
