    "No SmartHomeShop.io API key is connected, so no new cheap block can be planned. These schedules stay saved and start again as soon as prices are available.": "Es ist kein SmartHomeShop.io-API-Schlüssel verbunden, daher kann kein neuer günstiger Block geplant werden. Diese Zeitpläne bleiben gespeichert und starten wieder, sobald Preise verfügbar sind.",
