    "On after": "Ein nach",
    "On when export exceeds this. Its own draw creates the off-hysteresis.": "Schaltet ein, wenn die Einspeisung diesen Wert überschreitet. Der Eigenverbrauch des Geräts sorgt für die Ausschalthysterese.",
    "One connection unlocks live dynamic prices, cheapest-hours planning, deadline schedules and battery control. Create a free API key in your account and paste it here.": "Eine Verbindung schaltet dynamische Live-Preise, Planung nach günstigsten Stunden, Deadline-Zeitpläne und Batteriesteuerung frei. Erstelle in deinem Konto einen kostenlosen API-Schlüssel und füge ihn hier ein.",
    "One-click automations for this device - pick the ones you want and choose where the notification goes. Each becomes a normal Home Assistant automation you can fine-tune later in the automation editor.": "Ein-Klick-Automationen für dieses Gerät. Wähle die gewünschten aus und lege fest, wohin die Benachrichtigung geht. Jede wird zu einer normalen Home-Assistant-Automation, die du später im Automationseditor verfeinern kannst.",
