    "Preferred target SoC (%)": "Bevorzugter Ziel-SoC (%)",
    "Preferred: select a writable inverter active-power/output-limit number. Only use the switch fallback with the inverter manufacturer's safe enable control or a dedicated helper that calls that control. Never switch the inverter's AC supply with a smart plug, relay or contactor. The fallback can briefly export during every test start.": "Bevorzugt: Wähle eine beschreibbare numerische Entität für die Wirkleistung oder das Ausgangslimit des Wechselrichters. Nutze die Schalter-Ausweichlösung nur mit der sicheren Einschaltfunktion des Wechselrichterherstellers oder einem eigenen Helfer, der diese Funktion aufruft. Schalte die AC-Versorgung des Wechselrichters nie mit einer smarten Steckdose, einem Relais oder Schütz. Bei der Ausweichlösung kann es bei jedem Teststart kurz zu Einspeisung kommen.",
    "Presence": "Anwesenheit",
    "Price data is being fetched": "Preisdaten werden abgerufen",
    "Price day": "Preistag",
