    "Price, solar, battery wear and grid limits in one plan": "Preis, PV, Batterieverschleiß und Netzlimits in einem Plan",
    "Prices follow the active contract for this location and update by themselves when you change it in your SmartHomeShop account.": "Die Preise folgen dem aktiven Vertrag für diesen Standort und aktualisieren sich von selbst, wenn du ihn in deinem SmartHomeShop-Konto änderst.",
    "Producing now": "Erzeugt gerade",
    "Product settings": "Produkteinstellungen",
