    "Radar polygon coordinates must be finite numbers.": "Radar-Polygonkoordinaten müssen endliche Zahlen sein.",
    "Radar unavailable": "Radar nicht verfügbar",
    "Raise a thermostat setpoint during the cheapest block to store comfort, then lower it during the price peak. Uses the home as thermal storage.": "Erhöhe während des günstigsten Blocks den Sollwert eines Thermostats, um Wärme zu speichern, und senke ihn während der Preisspitze. Nutzt das Haus als Wärmespeicher.",
    "Raise the limit, or immediately restart a paused inverter, when grid import exceeds this value.": "Erhöhe das Limit oder starte einen pausierten Wechselrichter sofort neu, wenn der Netzbezug diesen Wert überschreitet.",
