    "Removal scope": "Umfang des Entfernens",
    "Remove": "Entfernen",
    "Remove both the SmartHomeShop link and ESPHome configuration. This does not erase the firmware or delete the node from the ESPHome dashboard.": "Entferne sowohl die SmartHomeShop-Verknüpfung als auch die ESPHome-Konfiguration. Die Firmware wird dabei nicht gelöscht und der Knoten bleibt im ESPHome-Dashboard.",
