    "Remove sensor": "Sensor entfernen",
    "Remove SmartHomeShop settings and derived entities. The ESPHome device and its original entities stay in Home Assistant.": "Entferne SmartHomeShop-Einstellungen und abgeleitete Entitäten. Das ESPHome-Gerät und seine ursprünglichen Entitäten bleiben in Home Assistant.",
    "Remove the battery planner and its automation?": "Batterieplaner und zugehörige Automation entfernen?",
    "Remove the SmartHomeShop link and hide this card. ESPHome, original entities, automations and recorder history stay unchanged. You can restore it later.": "Löse die SmartHomeShop-Verknüpfung und blende diese Karte aus. ESPHome, ursprüngliche Entitäten, Automationen und Verlauf bleiben unverändert. Du kannst das Gerät später wiederherstellen.",
    "Removing…": "Wird entfernt…",
