    "Reserve SoC must be below the target.": "Reserve-SoC muss unter dem Ziel liegen.",
    "Restart Home Assistant once to load the newly added cumulative import, export and normalised gas sensors needed by the Energy Dashboard.": "Starte Home Assistant einmal neu, um die neuen kumulativen Sensoren für Bezug und Einspeisung sowie die normalisierten Gassensoren zu laden, die das Energie-Dashboard braucht.",
