    "Run an opportunistic load whenever the price is at or below the daily average, and stop it when it rises above.": "Lass einen flexiblen Verbraucher laufen, solange der Preis auf oder unter dem Tagesdurchschnitt liegt, und stoppe ihn, sobald der Preis darüber steigt.",
