    "Schedule saved, but its sensor is not ready yet. Reopen and save again to create the automation.": "Zeitplan gespeichert, aber sein Sensor ist noch nicht bereit. Öffne ihn noch einmal und speichere ihn, um die Automation zu erstellen.",
