    "Select a control entity before enabling automatic control.": "Wähle eine Steuerungsentität aus, bevor du die automatische Steuerung aktivierst.",
    "Select a sensor when your inverter exposes the usable battery capacity. Its live value overrides the fixed value below.": "Wähle einen Sensor aus, wenn dein Wechselrichter die nutzbare Batteriekapazität bereitstellt. Sein Live-Wert überschreibt den festen Wert unten.",
