    "Separate parts belong to the same zone and share its presence state.": "Separate Teile gehören zur selben Zone und teilen sich deren Anwesenheitsstatus.",
    "Server URL - leave empty for the default. Only change this for self-hosting or local testing.": "Server-URL: Für den Standard leer lassen. Ändere dies nur für Self-Hosting oder lokale Tests.",
