    "Setting the meter reading is done on the device itself and requires the latest firmware. Update the firmware of your kit (via": "Der Zählerstand wird auf dem Gerät selbst eingestellt und erfordert die neueste Firmware. Aktualisiere die Firmware deines Kits (über",
