    "Show or hide the complete Smart Savings section on the Energy overview.": "Blende den gesamten Smart-Savings-Bereich in der Energieübersicht ein oder aus.",
    "Show Smart Savings": "Smart Savings anzeigen",
    "Show Smart Savings on the Energy overview": "Smart Savings in der Energieübersicht anzeigen",
