    "Your API key works, but the selected location has no active energy contract, so there are no prices to plan against. Add or activate a contract in your SmartHomeShop account, or pick another location in Settings.": "Dein API-Schlüssel funktioniert, aber der ausgewählte Standort hat keinen aktiven Energievertrag, daher gibt es keine Preise für die Planung. Füge in deinem SmartHomeShop-Konto einen Vertrag hinzu oder aktiviere ihn, oder wähle in den Einstellungen einen anderen Standort.",
    "Your P1 meter covers the grid. If you have solar panels or a home battery, connect their sensors so the Energy tab shows real surplus and state of charge. You can always do this later from Settings.": "Dein P1-Zähler deckt das Netz ab. Wenn du PV-Module oder einen Heimspeicher hast, verbinde deren Sensoren, damit der Tab Energie den echten Überschuss und den Ladezustand zeigt. Das kannst du auch später jederzeit in den Einstellungen tun.",
    "Your P1 meter only sees the grid. Connect your solar and battery entities (you already have them in Home Assistant) so we can see real solar surplus and your battery's charge level.": "Dein P1-Zähler sieht nur das Netz. Verbinde deine PV- und Batterie-Entitäten (die hast du bereits in Home Assistant), damit wir den echten PV-Überschuss und den Ladezustand deiner Batterie sehen können.",
