    "No mirrors added yet.": "Aucun miroir ajouté.",
    "Place the mirror on its real wall. Optional reflection protection filters predicted ghost targets behind it.": "Placez le miroir sur son mur réel. La protection anti-reflet facultative filtre les cibles fantômes prévues derrière lui.",
