    "Each protected mirror uses one of the radar's two exclusion slots. Raw diagnostic target entities remain unchanged; Room Designer, the UltimateSensor room view and firmware people counting ignore the protected area.": "Chaque miroir protégé utilise l’un des deux emplacements d’exclusion du radar. Les entités de diagnostic brutes restent inchangées ; Room Designer, la vue de pièce UltimateSensor et le comptage des personnes du micrologiciel ignorent la zone protégée.",
