    "Configure planning, limits, forecasts and automatic execution for your battery.": "Configurez la planification, les limites, les prévisions et l'exécution automatique de votre batterie.",
    "Configure price, solar, EV and inverter automations once for the whole home.": "Configurez une seule fois pour toute la maison les automatisations liées aux prix, au solaire, au VE et à l’onduleur.",
    "Configure your connection, energy sources, Home Assistant Energy, automations and battery.": "Configurez votre connexion, vos sources d’énergie, Home Assistant Énergie, vos automatisations et votre batterie.",
    "Confirmed prices are temporarily unavailable, so predicted prices are used.": "Les prix confirmés sont temporairement indisponibles, les prix prévus sont donc utilisés.",
    "Connect": "Connexion",
    "Connect once here to use your fixed, variable or dynamic energy contract across SmartHomeShop Energy. The integration keeps working locally without an account.": "Connectez-vous une fois ici pour utiliser votre contrat d’énergie fixe, variable ou dynamique dans tout SmartHomeShop Energy. L’intégration continue de fonctionner localement sans compte.",
    "Connect or select a P1 meter before linking the Home Assistant Energy Dashboard.": "Connectez ou sélectionnez un compteur P1 avant de lier le tableau de bord de l’énergie de Home Assistant.",
    "Connect or select a P1 meter first to configure smart energy automations.": "Connectez ou sélectionnez d’abord un compteur P1 pour configurer les automatisations Smart Energy.",
    "Connect the selected P1 meter to the native HA Energy Dashboard or import compatible HA source mappings into Smart Energy.": "Reliez le compteur P1 sélectionné au tableau de bord de l’énergie natif de HA ou importez les correspondances de sources HA compatibles dans Smart Energy.",
    "Connect your SmartHomeShop account to get dynamic prices, cheapest-hours planning and automated control.": "Connectez votre compte SmartHomeShop pour obtenir des prix dynamiques, une planification des heures les moins chères et un contrôle automatisé.",
    "Connect your SmartHomeShop account, select a contract and choose the P1 meter used across Smart Energy.": "Connectez votre compte SmartHomeShop, sélectionnez un contrat et choisissez le compteur P1 utilisé dans Smart Energy.",
    "Connect your SmartHomeShop.io devices via ESPHome, then add this integration via Settings → Devices & Services": "Connectez vos appareils SmartHomeShop.io via ESPHome, puis ajoutez cette intégration via Paramètres → Appareils et services",
    "Connected - your contract prices are being fetched.": "Connecté : vos prix contractuels sont en cours de récupération.",
    "Connected to Home Assistant, not yet to SmartHomeShop": "Connecté à Home Assistant, pas encore à SmartHomeShop",
    "Connected, but the selected location has no active energy contract yet, so there are no prices to show.": "Connecté, mais l'emplacement sélectionné n'a pas encore de contrat d'énergie actif, il n'y a donc pas de prix à afficher.",
    "Connected, but this location has no active energy contract yet. Add one in your SmartHomeShop account to see prices.": "Connecté, mais cet emplacement n'a pas encore de contrat d'énergie actif. Ajoutez-en un dans votre compte SmartHomeShop pour voir les prix.",
