    "One connection unlocks live dynamic prices, cheapest-hours planning, deadline schedules and battery control. Create a free API key in your account and paste it here.": "Une seule connexion donne accès aux prix dynamiques en direct, à la planification des heures les moins chères, aux plannings à échéance et au contrôle de la batterie. Créez une clé API gratuite dans votre compte et collez-la ici.",
