    "Select a control entity before enabling automatic control.": "Sélectionnez une entité de contrôle avant d'activer le contrôle automatique.",
    "Select a sensor when your inverter exposes the usable battery capacity. Its live value overrides the fixed value below.": "Sélectionnez un capteur si votre onduleur expose la capacité utilisable de la batterie. Sa valeur en direct remplace la valeur fixe ci-dessous.",
