    "Smart savings": "Smart Savings",
    "SmartHomeShop chooses the correct cumulative sensors and keeps other Energy Dashboard sources.": "SmartHomeShop choisit les bons capteurs cumulatifs et conserve les autres sources du tableau de bord de l’énergie.",
    "SmartHomeShop device": "Appareil SmartHomeShop",
    "SmartHomeShop Energy is pinned to a specific contract. Pick a location above to follow its active contract instead.": "SmartHomeShop Energy est épinglé sur un contrat spécifique. Choisissez un emplacement ci-dessus pour suivre plutôt son contrat actif.",
    "SmartHomeShop not linked": "SmartHomeShop non lié",
    "SmartHomeShop setup complete. The new energy sensors are ready.": "Configuration SmartHomeShop terminée. Les nouveaux capteurs d'énergie sont prêts.",
