    "Unlink SmartHomeShop": "Dissocier SmartHomeShop",
    "Unusual night-time power usage": "Consommation électrique nocturne inhabituelle",
    "Usable capacity (kWh)": "Capacité utilisable (kWh)",
    "Use automatic": "Utiliser le choix automatique",
    "Use firmware mounting": "Utiliser le montage du micrologiciel",
    "Use measured area": "Utiliser la zone mesurée",
    "Use solar surplus for a device": "Utiliser l'excédent solaire pour un appareil",
    "Use the lowest value accepted by the inverter. A small non-zero limit is safer for many models.": "Utilisez la valeur la plus basse acceptée par l'onduleur. Une petite limite non nulle est plus sûre pour de nombreux modèles.",
    "Used for the smart-savings estimate and the fuse guard below.": "Utilisé pour l’estimation Smart Savings et la protection de fusible ci-dessous.",
    "Used to stop charging at the target and to protect the reserve in battery arbitrage.": "Utilisé pour arrêter la charge à la cible et protéger la réserve lors de l’arbitrage de la batterie.",
    "Used when no capacity entity is selected or when that entity is temporarily unavailable.": "Utilisée lorsqu'aucune entité de capacité n'est sélectionnée ou lorsqu'elle est temporairement indisponible.",
    "Used when no load forecast is selected.": "Utilisé quand aucune prévision de charge n'est sélectionnée.",
    "Usually 100 for a percentage entity, or the inverter maximum for a watt-based entity.": "Habituellement 100 pour une entité en pourcentage, ou le maximum de l'onduleur pour une entité en watt.",
    "Visualization only": "Visualisation seulement",
    "Wait for the LD2460 installation settings before pushing zones": "Attendez les réglages d’installation du LD2460 avant d’envoyer les zones",
    "Waiting for capacity": "En attente de capacité",
    "Waiting for confirmed price data": "En attente de données de prix confirmées",
    "Waiting for the first complete plan.": "En attente du premier plan complet.",
    "Walk to each edge of the area the sensor can reliably detect. Stand still and select Mark. Your position is averaged over 5 seconds.": "Marchez jusqu’à chaque bord de la zone que le capteur peut détecter de façon fiable. Restez immobile et sélectionnez Mark. Votre position est moyennée sur 5 secondes.",
    "Wall mounted": "Montage mural",
    "Walls": "Murs",
    "Water": "Eau",
    "Water has been flowing non-stop - possible leak or running tap.": "L’eau coule sans arrêt : fuite possible ou robinet ouvert.",
    "Water is being used during the night.": "De l’eau est utilisée pendant la nuit.",
    "Water leak sensor wet": "Capteur de fuite d’eau mouillé",
    "water monitoring, leak detection and usage insights": "surveillance de l’eau, détection des fuites et analyse de la consommation",
    "water monitoring, leak detection, energy costs and insights": "surveillance de l’eau, détection des fuites, coûts énergétiques et analyses",
    "Water today": "Eau aujourd’hui",
    "Water total": "Total eau",
    "Welcome! Connect your SmartHomeShop account": "Bienvenue ! Connectez votre compte SmartHomeShop",
    "What smart energy earned": "Ce que Smart Energy a rapporté",
    "When the feed-in price goes negative (you would pay to export), switch on a diversion load to self-consume instead. Off again when feed-in is positive.": "Lorsque le tarif d’injection devient négatif et que vous paieriez pour injecter, activez plutôt une charge afin de consommer l’énergie sur place. Désactivez-la de nouveau lorsque le tarif redevient positif.",
    "Width (cm)": "Largeur (cm)",
    "Window type": "Type de fenêtre",
    "Writable inverter limit or safe enable control": "Limite d’onduleur modifiable ou commande d’activation sécurisée",
    "You are measuring the sensor, not the room": "Vous mesurez le capteur, pas la pièce",
    "You have unsaved changes in the Room Designer. Discard them?": "Vous avez des modifications non enregistrées dans le Room Designer. Les abandonner ?",
    "You have unsaved changes. Discard them?": "Vous avez des modifications non enregistrées. Les abandonner ?",
    "You need an administrator account to create automations.": "Vous avez besoin d’un compte administrateur pour créer des automatisations.",
    "Your API key works, but the selected location has no active energy contract, so there are no prices to plan against. Add or activate a contract in your SmartHomeShop account, or pick another location in Settings.": "Votre clé API fonctionne, mais l’emplacement sélectionné n’a pas de contrat d’énergie actif, il n’y a donc aucun prix sur lequel baser la planification. Ajoutez ou activez un contrat dans votre compte SmartHomeShop, ou choisissez un autre emplacement dans Paramètres.",
    "Your P1 meter covers the grid. If you have solar panels or a home battery, connect their sensors so the Energy tab shows real surplus and state of charge. You can always do this later from Settings.": "Votre compteur P1 couvre le réseau. Si vous avez des panneaux solaires ou une batterie domestique, connectez leurs capteurs pour que l’onglet Énergie affiche le surplus réel et l’état de charge. Vous pourrez toujours le faire plus tard depuis Paramètres.",
    "Your P1 meter only sees the grid. Connect your solar and battery entities (you already have them in Home Assistant) so we can see real solar surplus and your battery's charge level.": "Votre compteur P1 ne voit que le réseau. Connectez vos entités solaires et de batterie (vous les avez déjà dans Home Assistant) pour que nous puissions voir le surplus solaire réel et le niveau de charge de votre batterie.",
