    "Notify when power stays above a limit between midnight and 06:00.": "Notificar cuando la potencia se mantenga por encima de un límite entre la medianoche y las 06:00.",
    "Notify when smart leak detection flags unusual usage.": "Notificar cuando la detección inteligente de fugas señale un consumo inusual.",
