    "On after": "Encender tras",
    "On when export exceeds this. Its own draw creates the off-hysteresis.": "Se enciende cuando el vertido a la red supera este valor. Su propio consumo crea la histéresis de apagado.",
    "One connection unlocks live dynamic prices, cheapest-hours planning, deadline schedules and battery control. Create a free API key in your account and paste it here.": "Una sola conexión desbloquea precios dinámicos en tiempo real, planificación de las horas más baratas, programaciones con hora límite y control de la batería. Crea una clave de API gratuita en tu cuenta y pégala aquí.",
    "One-click automations for this device - pick the ones you want and choose where the notification goes. Each becomes a normal Home Assistant automation you can fine-tune later in the automation editor.": "Automatizaciones de un clic para este dispositivo: elige las que quieras y adónde va la notificación. Cada una se convierte en una automatización normal de Home Assistant que puedes ajustar después en el editor de automatizaciones.",
    "Online": "En línea",
    "Only grid power is connected. Add your solar and battery entities to see production, storage and state of charge.": "Solo está conectada la energía de la red. Añade tus entidades solares y de batería para ver la producción, el almacenamiento y el estado de carga.",
    "Only the name changes. Your layout, sensors and zones stay in place.": "Solo cambia el nombre. Tu diseño, sensores y zonas se mantienen en su sitio.",
    "Only this sensor counts crossings on this line, so people are not counted twice.": "Solo este sensor cuenta los cruces en esta línea, para que las personas no se cuenten dos veces.",
