    "Preferred: select a writable inverter active-power/output-limit number. Only use the switch fallback with the inverter manufacturer's safe enable control or a dedicated helper that calls that control. Never switch the inverter's AC supply with a smart plug, relay or contactor. The fallback can briefly export during every test start.": "Preferido: selecciona una entidad numérica editable de potencia activa o límite de salida del inversor. Usa la alternativa con interruptor solo con el control de habilitación seguro del fabricante del inversor o con un ayudante dedicado que llame a ese control. Nunca conmutes la alimentación de CA del inversor con un enchufe inteligente, relé o contactor. La alternativa puede verter brevemente a la red en cada arranque de prueba.",
