    "State-of-charge sensor": "Sensor de estado de carga",
    "Steer devices around prices and solar production. Loads can run in cheap or surplus hours, while inverter output can be reduced safely to avoid unwanted export. Each setup creates a normal, editable Home Assistant automation with restart recovery and fail-safe behaviour.": "Controla los dispositivos según los precios y la producción solar. Las cargas pueden funcionar en horas baratas o con excedente, mientras que la salida del inversor se puede reducir de forma segura para evitar vertidos no deseados. Cada configuración crea una automatización normal y editable de Home Assistant con recuperación tras reinicio y comportamiento seguro ante fallos.",
    "Surplus needed": "Excedente necesario",
    "Switch a deferrable load (boiler, pump, ventilation) on during the cheapest contiguous block of the day and off when it ends.": "Enciende una carga aplazable (termo, bomba, ventilación) durante el bloque continuo más barato del día y apágala cuando termine.",
    "Switch a load off when the price level hits its daily peak and back on when it drops. Trims the most expensive hours.": "Apaga una carga cuando el nivel de precios alcance su pico diario y vuelve a encenderla cuando baje. Evita las horas más caras.",
    "Switch a load on when the house exports more than it needs, and off when you would start importing - with hysteresis + dwell so it does not flap.": "Enciende una carga cuando la casa vierte más de lo que necesita y apágala cuando empezarías a importar, con histéresis y tiempo de espera para que no conmute sin parar.",
