export const panelLanguage = (hass: HassLanguage | undefined): SupportedPanelLanguage => {
  const raw = hass?.language || hass?.locale?.language || 'en';
  const language = raw.toLowerCase().replace('_', '-').split('-')[0];
  return SUPPORTED_PANEL_LANGUAGES.includes(language as SupportedPanelLanguage)
    ? language as SupportedPanelLanguage
    : 'en';
};

const interpolate = (template: string, variables: Record<string, string | number>): string =>
  template.replace(/\{(\w+)\}/g, (match, key) =>
    Object.prototype.hasOwnProperty.call(variables, key) ? String(variables[key]) : match);

const PREFIX_CACHE = new Map<string, string>();

const translatedTemplate = (language: SupportedPanelLanguage, source: string): string => {
  if (language === 'en') return source;
  const dictionary = PANEL_TRANSLATIONS[language];
  const exact = dictionary?.[source];
  if (exact) return exact;

  // Service-call errors often append a technical detail to a translated,
  // human-readable sentence. Translate that stable prefix while preserving
  // the original Home Assistant error detail verbatim.
  const cacheKey = `${language}\u0000${source}`;
  const cached = PREFIX_CACHE.get(cacheKey);
  if (cached) return cached;
  if (source.length >= 20) {
    const prefix = Object.keys(dictionary || {})
      .filter(candidate => candidate.length >= 12 && /[.!?:]$/.test(candidate) && source.startsWith(`${candidate} `))
      .sort((left, right) => right.length - left.length)[0];
    if (prefix) {
      const result = `${dictionary[prefix]}${source.slice(prefix.length)}`;
      PREFIX_CACHE.set(cacheKey, result);
      return result;
    }
  }
  PREFIX_CACHE.set(cacheKey, source);
  return source;
};

export const panelText = (
  hass: HassLanguage | undefined,
  source: string,
  variables: Record<string, string | number> = {},
): string => {
  const language = panelLanguage(hass);
  const template = translatedTemplate(language, source);
  return interpolate(template, variables);
};

const TEXT_STATE = new WeakMap<Text, { source: string; lastApplied: string }>();
const ATTRIBUTE_STATE = new WeakMap<Element, Map<string, { source: string; lastApplied: string }>>();
const TRANSLATABLE_ATTRIBUTES = ['aria-label', 'aria-description', 'title', 'placeholder', 'alt'] as const;

const splitWhitespace = (value: string): { prefix: string; text: string; suffix: string } => {
  const prefix = value.match(/^\s*/)?.[0] || '';
  const suffix = value.match(/\s*$/)?.[0] || '';
  return { prefix, text: value.trim().replace(/\s+/g, ' '), suffix };
};

const translateTextNode = (node: Text, hass: HassLanguage | undefined): void => {
  const parent = node.parentElement;
  if (!parent || parent.closest('[data-i18n-ignore], code, pre, script, style')) return;

  const current = node.data;
  const previous = TEXT_STATE.get(node);
  const sourceValue = previous && current === previous.lastApplied ? previous.source : current;
  const { prefix, text, suffix } = splitWhitespace(sourceValue);
  if (!text) return;

  const translated = panelText(hass, text);
  const next = `${prefix}${translated}${suffix}`;
  TEXT_STATE.set(node, { source: sourceValue, lastApplied: next });
  if (current !== next) node.data = next;
};

const translateAttributes = (element: Element, hass: HassLanguage | undefined): void => {
  let states = ATTRIBUTE_STATE.get(element);
  if (!states) {
    states = new Map();
    ATTRIBUTE_STATE.set(element, states);
  }

  for (const attribute of TRANSLATABLE_ATTRIBUTES) {
    if (!element.hasAttribute(attribute)) continue;
    const current = element.getAttribute(attribute) || '';
    const previous = states.get(attribute);
    const source = previous && current === previous.lastApplied ? previous.source : current;
    const next = panelText(hass, source);
    states.set(attribute, { source, lastApplied: next });
    if (current !== next) element.setAttribute(attribute, next);
  }
};

/**
 * Localises the rendered panel without changing entity IDs, device names or
 * service payloads. Lit keeps rendering its normal templates; this layer only
 * replaces known UI copy and accessible attributes after each render.
 */
export const installPanelLocalization = (
  root: ShadowRoot,
  hassProvider: () => HassLanguage | undefined,
): { refresh: () => void; disconnect: () => void } => {
  const observedRoots = new WeakSet<ShadowRoot>();
  const observers = new Set<MutationObserver>();
  const scheduledRoots = new WeakSet<ShadowRoot>();

  const localizeRoot = (currentRoot: ShadowRoot): void => {
    const walker = document.createTreeWalker(currentRoot, NodeFilter.SHOW_TEXT);
    let node = walker.nextNode();
    while (node) {
      translateTextNode(node as Text, hassProvider());
      node = walker.nextNode();
    }

    for (const element of Array.from(currentRoot.querySelectorAll('*'))) {
      translateAttributes(element, hassProvider());
      if (element.shadowRoot) observeRoot(element.shadowRoot);
    }
  };

  const schedule = (currentRoot: ShadowRoot): void => {
    if (scheduledRoots.has(currentRoot)) return;
    scheduledRoots.add(currentRoot);
    queueMicrotask(() => {
      scheduledRoots.delete(currentRoot);
      localizeRoot(currentRoot);
    });
  };

  function observeRoot(currentRoot: ShadowRoot): void {
    if (observedRoots.has(currentRoot)) return;
    observedRoots.add(currentRoot);
    const observer = new MutationObserver(() => schedule(currentRoot));
    observer.observe(currentRoot, {
      subtree: true,
      childList: true,
      characterData: true,
      attributes: true,
      attributeFilter: [...TRANSLATABLE_ATTRIBUTES],
    });
    observers.add(observer);
    localizeRoot(currentRoot);
  }

  observeRoot(root);
  return {
    refresh: () => localizeRoot(root),
    disconnect: () => {
      for (const observer of observers) observer.disconnect();
      observers.clear();
    },
  };
};

export { PANEL_TRANSLATIONS };
